from __future__ import annotations

import pytest

from zoom_sonos_detector import config as cfg_mod


def _base(**overrides):
    data = {
        "unifi": {"base_url": "https://192.168.1.1", "api_key": "k"},
        "watch": {"macs": ["AA:BB:CC:DD:EE:FF"]},
    }
    for section, vals in overrides.items():
        data.setdefault(section, {}).update(vals)
    return data


def test_defaults_applied_when_timing_omitted():
    c = cfg_mod.from_dict(_base())
    assert c.timing.poll_interval_s == 2.0
    assert c.timing.pause_debounce_s == 10.0
    assert c.timing.resume_debounce_s == 30.0
    assert c.log_level == "INFO"


def test_macs_normalized_lowercase():
    c = cfg_mod.from_dict(_base())
    assert c.watched_macs == frozenset({"aa:bb:cc:dd:ee:ff"})


def test_custom_timing_honored():
    c = cfg_mod.from_dict(_base(timing={"poll_interval_s": 1, "pause_debounce_s": 5, "resume_debounce_s": 15}))
    assert c.timing.poll_interval_s == 1
    assert c.timing.pause_debounce_s == 5
    assert c.timing.resume_debounce_s == 15


def test_missing_unifi_section_raises():
    with pytest.raises(ValueError, match="missing \\[unifi\\]"):
        cfg_mod.from_dict({"watch": {"macs": ["aa:bb:cc:dd:ee:ff"]}})


def test_missing_base_url_raises():
    with pytest.raises(ValueError, match="base_url"):
        cfg_mod.from_dict({"unifi": {"api_key": "k"}, "watch": {"macs": ["aa:bb:cc:dd:ee:ff"]}})


def test_no_auth_raises():
    with pytest.raises(ValueError, match="api_key"):
        cfg_mod.from_dict({"unifi": {"base_url": "https://x"}, "watch": {"macs": ["aa:bb:cc:dd:ee:ff"]}})


def test_userpass_auth_accepted():
    c = cfg_mod.from_dict({
        "unifi": {"base_url": "https://x", "username": "u", "password": "p"},
