    })
    assert c.unifi.username == "u" and c.unifi.password == "p"
    assert c.unifi.api_key is None


def test_missing_macs_raises():
    with pytest.raises(ValueError, match="macs"):
        cfg_mod.from_dict({"unifi": {"base_url": "https://x", "api_key": "k"}})


def test_empty_macs_raises():
    with pytest.raises(ValueError, match="macs"):
        cfg_mod.from_dict({"unifi": {"base_url": "https://x", "api_key": "k"}, "watch": {"macs": []}})

