from __future__ import annotations

from zoom_sonos_detector import unifi as unifi_mod


def test_zoom_bytes_none_when_no_dpi_stats():
    assert unifi_mod._zoom_bytes_for_client({"mac": "aa:bb:cc:dd:ee:ff"}) is None


def test_zoom_bytes_none_when_dpi_has_no_zoom():
    client = {
        "mac": "aa:bb:cc:dd:ee:ff",
        "dpi_stats": [
            {"app": "youtube", "cat": "video", "rx_bytes": 1000, "tx_bytes": 50},
            {"app": "slack", "cat": "messaging", "rx_bytes": 200, "tx_bytes": 100},
        ],
    }
    assert unifi_mod._zoom_bytes_for_client(client) is None


def test_zoom_bytes_sum_when_dpi_has_zoom():
    client = {
        "dpi_stats": [
            {"app": "slack", "rx_bytes": 10, "tx_bytes": 5},
            {"app": "Zoom", "cat": "voip", "rx_bytes": 1000, "tx_bytes": 500},
        ],
    }
    assert unifi_mod._zoom_bytes_for_client(client) == 1500


def test_zoom_bytes_matches_category_field():
    client = {
        "dpi_stats": [
            {"app": "unknown", "cat": "Zoom Meetings", "rx_bytes": 200, "tx_bytes": 300},
        ],
    }
    assert unifi_mod._zoom_bytes_for_client(client) == 500


def test_zoom_bytes_prefers_dpi_stats_last_when_present():
    client = {
        "dpi_stats": [{"app": "zoom", "rx_bytes": 9999, "tx_bytes": 0}],
        "dpi_stats_last": [{"app": "zoom", "rx_bytes": 200, "tx_bytes": 100}],
    }
    # "dpi_stats_last" is the most recent bucket — prefer it if present.
    assert unifi_mod._zoom_bytes_for_client(client) == 300
